<?php
declare(strict_types=1);
function normalize_english_text(string $text): string { $text=mb_strtolower($text,'UTF-8'); $text=preg_replace("/[^a-z0-9'\s]+/u",' ',$text); return preg_replace('/\s+/',' ',trim($text)); }
function word_list(string $text): array { $n=normalize_english_text($text); return $n===''?[]:array_values(array_filter(explode(' ',$n))); }
function word_sequence_similarity(array $target,array $heard): float { if(!$target&&!$heard)return 100.0; if(!$target||!$heard)return 0.0; $m=count($target);$n=count($heard);$dp=array_fill(0,$m+1,array_fill(0,$n+1,0)); for($i=1;$i<=$m;$i++){for($j=1;$j<=$n;$j++){$dp[$i][$j]=$target[$i-1]===$heard[$j-1]?$dp[$i-1][$j-1]+1:max($dp[$i-1][$j],$dp[$i][$j-1]);}} return round(($dp[$m][$n]/max($m,$n))*100,2); }
function compare_pronunciation_words(string $targetText,string $heardText): array { $target=word_list($targetText);$heard=word_list($heardText);$matched=[];$missing=[];$unexpected=$heard; foreach($target as $word){$idx=array_search($word,$unexpected,true); if($idx!==false){$matched[]=$word;unset($unexpected[$idx]);$unexpected=array_values($unexpected);}else{$missing[]=$word;}} return ['matched_words'=>$matched,'missing_words'=>$missing,'unexpected_words'=>array_values($unexpected),'similarity_score'=>word_sequence_similarity($target,$heard)]; }
function build_pronunciation_feedback(array $c): string { $s=(float)$c['similarity_score']; if($s>=90)return 'Muito bom. Repita mais uma vez buscando ritmo natural.'; if($s>=70)return $c['missing_words']?'Boa tentativa. Repita com atenção: '.implode(', ',array_slice($c['missing_words'],0,3)).'.':'Boa tentativa. Repita um pouco mais devagar.'; return $c['missing_words']?'Vamos por partes. Primeiro pratique: '.implode(', ',array_slice($c['missing_words'],0,4)).'.':'Fale mais devagar e repita em blocos menores.'; }
